def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    cells6 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not cells4 or not cells6:
        return out
    r0, r1 = min(r for r, c in cells4), max(r for r, c in cells4)
    c0, c1 = min(c for r, c in cells4), max(c for r, c in cells4)
    # Marker aspect/orientation: vertically arranged marker means reflect down;
    # horizontally arranged marker means reflect to the right.
    mr0, mr1 = min(r for r, c in cells6), max(r for r, c in cells6)
    mc0, mc1 = min(c for r, c in cells6), max(c for r, c in cells6)
    for r, c in cells6:
        out[r][c] = 0
    if mr1 - mr0 >= mc1 - mc0:  # vertical reflection copy below
        for r, c in cells4:
            rr = r1 + 1 + (r1 - r)
            if rr < h:
                out[rr][c] = 4
    else:  # horizontal reflection copy to the right
        for r, c in cells4:
            cc = c1 + 1 + (c1 - c)
            if cc < w:
                out[r][cc] = 4
    return out
